            Task time
          </div>
        </div>
        <div style={{ width: 36, height: 36, borderRadius: 12, display: 'grid', placeItems: 'center', background: 'rgba(132, 204, 22, 0.12)', color: '#bef264', fontSize: 18 }}>
          ⏱
        </div>
      </header>

      <section style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10 }}>
        <label style={{ display: 'grid', gap: 6, color: '#a7b0c0', fontSize: 12, fontWeight: 650 }}>
