            disabled={!interactionEnabled}
            value={minutesPerTask}
            onChange={(event) => updateValue('minutesPerTask', event.target.value)}
            style={{ boxSizing: 'border-box', width: '100%', height: 42, padding: '0 12px', borderRadius: 11, border: '1px solid rgba(255,255,255,0.13)', outline: 'none', background: '#10141b', color: '#f7f8fb', fontSize: 17, fontWeight: 700 }}
          />
        </label>
      </section>

      <section style={{ display: 'flex', alignItems: 'end', justifyContent: 'space-between', padding: '13px 15px', borderRadius: 14, background: 'rgba(190, 242, 100, 0.09)', border: '1px solid rgba(190, 242, 100, 0.18)' }}>
